var UpdateWorkInSystemCnt;

UpdateWorkInSystemCnt = function() {
  var context, source, template;
  source = '{{#ifCond data.activeSessions.length "<" 20}} <table class="table table-bordered table-hover table-condensed"> {{else}} <table class="table table-xs table-bordered table-hover table-condensed"> {{/ifCond}} <thead> <th>№</th> {{#if data.activeSessions.0.eoName}} <th>{{context.kEO}}</th> {{/if}} <th>{{context.kDisplayName}}</th> {{#if data.activeSessions.0.ip}} <th>{{context.kUserName}}</th> <th>{{context.kLoginTime}}</th> <th>ip</th> {{/if}} <th>{{context.kRoles}}</th> </thead> {{#if data.activeSessions}} {{#if data.activeSessions.0.eoName}} {{#each data.activeSessions}} <tr> <td class="text-right">{{match @index}}</td> <td>{{eoName}}</td> <td>{{nickName}}</td> <td>{{loginName}}</td> <td>{{currentDate loginTime}}</td> <td>{{ip}}</td> <td>{{roles}}</td> </tr> {{/each}} {{else}} {{#if data.activeSessions.0.ip}} {{#each data.activeSessions}} <tr> <td class="text-right">{{match @index}}</td> <td>{{nickName}}</td> <td>{{loginName}}</td> <td>{{currentDate loginTime}}</td> <td>{{ip}}</td> <td>{{roles}}</td> </tr> {{/each}} {{else}} {{#each data.activeSessions}} <tr> <td class="text-right">{{match @index}}</td> <td>{{nickName}}</td> <td>{{roles}}</td> </tr> {{/each}} {{/if}} {{/if}} {{else}} <tr><td colspan="8" class="body" align="center">Нет пользователей в системе Сетевой Город. Образование</td></tr> {{/if}} </table>';
  template = Handlebars.compile(source);
  jsSubmit({
    action: "/webapi/context/activeSessions",
    method: "get",
    showProcessing: true,
    onSuccess: function(activeSessions) {
      var activeSessionCount, container;
      container = $("<div class=\"table-responsive\" style=\"max-height: 600px;\"></div>");
      container.html(template({
        context: context,
        data: {
          activeSessions: activeSessions
        }
      }));
      activeSessionCount = activeSessions != null ? activeSessions.length : void 0;
      $('#WorkingInSystemCnt').text(activeSessionCount);
      return $.show.dialog({
        title: 'Список пользователей в сети',
        message: container,
        size: BootstrapDialog.SIZE_WIDE
      });
    }
  });
  return context = {
    kEO: language.Generic.Common.kEO,
    kDisplayName: language.Generic.Common.kDisplayName,
    kUserName: language.Generic.Common.kUserName,
    kLoginTime: language.Generic.ServAdmin.kLoginTime,
    kRoles: language.Generic.Common.kRoles
  };
};

window.sys = $.extend(typeof sys !== "undefined" && sys !== null ? sys : {}, {
  mail: (function() {
    var groupsBuilder, mailMngr, recipientInfo, recipientsBuilder;
    mailMngr = (function() {
      function mailMngr() {}


      /*@messageData:
      				theme				- тема
      				to					- получатели "кому"
      				copy				- получатели "копия"
      				text				- текст письма
       */

      mailMngr.prototype.compose = function(messageData) {
        var Wnd, mailPostParams, url, winOptions;
        this.messageData = messageData;
        mailPostParams = {
          theme: this.messageData.theme || "",
          text: this.messageData.text || ""
        };
        if (this.messageData.to) {
          mailPostParams.to_id = this.messageData.to.id;
          mailPostParams.to_name = this.messageData.to.displayText;
        }
        if (this.messageData.sendReport) {
          mailPostParams.sendReport = true;
        }
        if (this.messageData.copy) {
          mailPostParams.copy_id = this.messageData.copy.id;
          mailPostParams.copy_name = this.messageData.copy.displayText;
        }
        url = urlHelper.makeUrl("/app/popup/mail/compose/", mailPostParams);
        Wnd = null;
        winOptions = {
          url: url,
          name: '_composemessage',
          specs: 'status=yes, toolbar=no,menubar=no,location=no,scrollbars=yes,resizable=yes,directories=no,width=820,height=620',
          winChild: Wnd
        };
        windowOpen(winOptions);
        Wnd = winOptions.winChild;
        Wnd.name = '_composemessage';
        if (!Wnd) {
          throw "ошибка отрытия окна почты";
        }
        center(Wnd, 500, 520);
        return postTo(url, mailPostParams, {
          target: Wnd.name
        });
      };

      mailMngr.prototype.inbox = function() {
        return openPopupWindow("_mail_new", "/app/popup/mail/mailbox/", 950, 660);
      };

      mailMngr.prototype.getRecipientBuilder = function() {
        return new recipientsBuilder;
      };

      return mailMngr;

    })();
    recipientInfo = (function() {
      function recipientInfo(id1, displayText1) {
        this.id = id1;
        this.displayText = displayText1;
      }

      return recipientInfo;

    })();
    groupsBuilder = (function() {
      function groupsBuilder(recipientsBuilder1) {
        this.recipientsBuilder = recipientsBuilder1;
      }

      groupsBuilder.prototype.admins = function(orgId, orgName) {
        var recipient;
        recipient = new recipientInfo("A" + orgId, language.Generic.Common.kToAdministration + " " + orgName);
        this.recipientsBuilder.addRecipient(recipient);
        return this;
      };

      groupsBuilder.prototype.end = function() {
        return this.recipientsBuilder;
      };

      return groupsBuilder;

    })();
    recipientsBuilder = (function() {
      function recipientsBuilder() {
        this.recipients = [];
        this.groups = new groupsBuilder(this);
      }

      recipientsBuilder.prototype.addRecipient = function(recipient) {
        return this.recipients.push(recipient);
      };

      recipientsBuilder.prototype.end = function() {
        var displayText, i, id, len, recipient, ref;
        id = "";
        displayText = "";
        ref = this.recipients;
        for (i = 0, len = ref.length; i < len; i++) {
          recipient = ref[i];
          id += ", " + recipient.id;
          displayText += ", " + recipient.displayText;
        }
        id = id.substring(2);
        displayText = displayText.substring(2);
        return new recipientInfo(id, displayText);
      };

      return recipientsBuilder;

    })();
    return new mailMngr;
  })()
});

